{"g":3,"b":2,"k":"o","q":"Hvad betyder 'garden'?","o":["have","garage","gård","gardin"],"a":"have","r":"'Garden' betyder have. Gardin hedder 'curtain'."},
{"g":3,"b":2,"k":"o","q":"Hvad betyder 'window'?","o":["vind","væg","dør","vindue"],"a":"vindue","r":"'Window' betyder vindue. Væg hedder 'wall'."},
{"g":3,"b":2,"k":"o","q":"Hvad hedder 'gulerod' på engelsk?","o":["cabbage","potato","carrot","corn"],"a":"carrot","r":"Gulerod = carrot. Kartoffel = potato."},
{"g":3,"b":2,"k":"o","q":"Hvad betyder 'potato'?","o":["tomat","kartoffel","pære","løg"],"a":"kartoffel","r":"'Potato' betyder kartoffel. 'Chips' laves af kartofler."},
{"g":3,"b":2,"k":"o","q":"Hvad betyder 'chicken'?","o":["kylling","kirke","ko","køkken"],"a":"kylling","r":"'Chicken' betyder kylling eller høne."},
{"g":3,"b":2,"k":"o","q":"Hvad hedder 'appelsin' på engelsk?","o":["apple","lemon","grape","orange"],"a":"orange","r":"Appelsin = orange. Samme ord som farven orange."},
{"g":3,"b":2,"k":"o","q":"Hvad betyder 'juice'?","o":["suppe","sukker","saft eller juice","salt"],"a":"saft eller juice","r":"'Juice' er juice eller saft — f.eks. 'orange juice'."},
{"g":3,"b":2,"k":"o","q":"Hvad hedder 'suppe' på engelsk?","o":["soap","soup","salt","sugar"],"a":"soup","r":"Suppe = soup. Pas på: 'soap' er sæbe!"},
{"g":3,"b":2,"k":"o","q":"Hvad betyder 'breakfast'?","o":["morgenmad","frokost","aftensmad","mellemmåltid"],"a":"morgenmad","r":"'Breakfast' er morgenmad. Frokost = lunch, aftensmad = dinner."},
{"g":3,"b":2,"k":"o","q":"Hvad betyder 'lunch'?","o":["morgenmad","aftensmad","kage","frokost"],"a":"frokost","r":"'Lunch' er frokost. Madpakke hedder 'packed lunch'."},
{"g":3,"b":2,"k":"o","q":"Hvad betyder 'run'?","o":["ryste","rulle","løbe","ride"],"a":"løbe","r":"'Run' betyder løbe. 'I run fast' = jeg løber hurtigt."},
{"g":3,"b":2,"k":"o","q":"Hvad hedder 'hoppe' på engelsk?","o":["run","jump","swim","sit"],"a":"jump","r":"Hoppe = jump. Svømme = swim."},
{"g":3,"b":2,"k":"o","q":"Hvad betyder 'swim'?","o":["svømme","svinge","synge","sove"],"a":"svømme","r":"'Swim' betyder svømme. Synge hedder 'sing'."},
{"g":3,"b":2,"k":"o","q":"Hvad betyder 'sleep'?","o":["slippe","slå","sidde","sove"],"a":"sove","r":"'Sleep' betyder sove. 'Go to sleep' = gå i seng og sove."},
{"g":3,"b":2,"k":"o","q":"Hvad hedder 'synge' på engelsk?","o":["sit","sink","sing","swing"],"a":"sing","r":"Synge = sing. 'Sit' betyder sidde."},
{"g":3,"b":2,"k":"o","q":"Hvad betyder 'eat'?","o":["drikke","spise","lege","læse"],"a":"spise","r":"'Eat' betyder spise. Drikke hedder 'drink'."},
{"g":3,"b":2,"k":"o","q":"Hvad betyder 'read'?","o":["læse","ride","rød","regne"],"a":"læse","r":"'Read' betyder læse. 'I read a book' = jeg læser en bog."},
{"g":3,"b":2,"k":"o","q":"Hvad betyder 'play'?","o":["plante","betale","pleje","lege eller spille"],"a":"lege eller spille","r":"'Play' betyder lege eller spille: 'play football' = spille fodbold."},
{"g":3,"b":2,"k":"o","q":"Hvad hedder 'abe' på engelsk?","o":["money","donkey","monkey","mouse"],"a":"monkey","r":"Abe = monkey. 'Money' er penge, og 'donkey' er et æsel."},
{"g":3,"b":2,"k":"o","q":"Hvad betyder 'bear'?","o":["bær","bjørn","øl","bi"],"a":"bjørn","r":"'Bear' betyder bjørn. Bær hedder 'berry'."},
{"g":3,"b":2,"k":"o","q":"Hvad betyder 'frog'?","o":["frø","fisk","fugl","frugt"],"a":"frø","r":"'Frog' betyder frø. Frugt hedder 'fruit'."},
{"g":3,"b":2,"k":"o","q":"Hvad hedder 'slange' på engelsk?","o":["snail","snow","shark","snake"],"a":"snake","r":"Slange = snake. 'Snail' er en snegl, 'shark' er en haj."},
{"g":3,"b":2,"k":"o","q":"Hvad betyder 'small'?","o":["stor","smal","lille","sød"],"a":"lille","r":"'Small' betyder lille. Det modsatte er 'big'."},
{"g":3,"b":2,"k":"o","q":"Hvad betyder 'fast'?","o":["fast","hurtig","langsom","fed"],"a":"hurtig","r":"'Fast' betyder hurtig på engelsk. Langsom hedder 'slow'."},
{"g":3,"b":2,"k":"o","q":"Hvad betyder 'old'?","o":["gammel","ny","ung","kold"],"a":"gammel","r":"'Old' betyder gammel. Ung hedder 'young'."},
{"g":3,"b":2,"k":"o","q":"Hvad betyder 'funny'?","o":["fin","sur","fræk","sjov"],"a":"sjov","r":"'Funny' betyder sjov. 'A funny joke' = en sjov vits."},
{"g":3,"b":2,"k":"o","q":"Hvad betyder 'sock'?","o":["sko","sæk","sok","sukker"],"a":"sok","r":"'Sock' betyder sok. Sko hedder 'shoe'."},
{"g":3,"b":2,"k":"o","q":"Hvad hedder 'kjole' på engelsk?","o":["dish","dress","desk","door"],"a":"dress","r":"Kjole = dress. 'Desk' er et skrivebord."},
{"g":3,"b":2,"k":"o","q":"Hvad betyder 'trousers'?","o":["bukser","trøje","sko","strømper"],"a":"bukser","r":"'Trousers' betyder bukser (på amerikansk: 'pants')."},
{"g":3,"b":2,"k":"h","q":"Hvad betyder 'How are you?'","o":["Hvor er du?","Hvem er du?","Hvor gammel er du?","Hvordan har du det?"],"a":"Hvordan har du det?","r":"'How are you?' spørger, hvordan man har det. Man kan svare: 'I'm fine, thank you.'"},
{"g":3,"b":2,"k":"h","q":"Hvad betyder 'Nice to meet you'?","o":["Vi ses i morgen","Hvad hedder du?","Rart at møde dig","Godt gået"],"a":"Rart at møde dig","r":"Man siger 'Nice to meet you', når man møder en ny person."},
{"g":3,"b":2,"k":"h","q":"Hvad betyder 'Where do you live?'","o":["Hvad laver du?","Hvor bor du?","Hvornår kommer du?","Hvem bor du med?"],"a":"Hvor bor du?","r":"'Where' = hvor, 'live' = bor. Svar: 'I live in Denmark.'"},
{"g":3,"b":2,"k":"h","q":"Hvad betyder 'I live in Denmark'?","o":["Jeg bor i Danmark","Jeg elsker Danmark","Jeg rejser til Danmark","Jeg kommer fra Norge"],"a":"Jeg bor i Danmark","r":"'Live' betyder bo. 'I live in Denmark' = jeg bor i Danmark."},
{"g":3,"b":2,"k":"h","q":"Hvad betyder 'Well done!'?","o":["Godt nytår!","Skynd dig!","Pas på!","Godt gået!"],"a":"Godt gået!","r":"'Well done' siger man, når nogen har klaret noget godt."},
{"g":3,"b":2,"k":"h","q":"Hvad betyder 'Come here!'?","o":["Gå væk!","Sid ned!","Kom her!","Vent lidt!"],"a":"Kom her!","r":"'Come' betyder kom, og 'here' betyder her."},
{"g":3,"b":2,"k":"h","q":"Hvad betyder 'Sit down, please'?","o":["Rejs dig op, tak","Sæt dig ned, tak","Gå ud, tak","Ti stille, tak"],"a":"Sæt dig ned, tak","r":"'Sit down' betyder sæt dig ned. Rejs dig = 'stand up'."},
{"g":3,"b":2,"k":"h","q":"Hvad siger læreren, når man skal række hånden op?","o":["Put your hand up.","Put your hat on.","Give me your hand.","Wash your hands."],"a":"Put your hand up.","r":"'Put your hand up' = ræk hånden op. 'Hand' er hånd."},
{"g":3,"b":2,"k":"h","q":"Hvad betyder 'I don't know'?","o":["Jeg kan ikke lide det","Jeg vil ikke","Jeg har det ikke","Jeg ved det ikke"],"a":"Jeg ved det ikke","r":"'Know' betyder vide. 'I don't know' = jeg ved det ikke."},
{"g":3,"b":2,"k":"h","q":"Hvad betyder 'Let's play!'?","o":["Lad være!","Lad os spise!","Lad os lege!","Lad os gå hjem!"],"a":"Lad os lege!","r":"'Let's' betyder 'lad os', og 'play' betyder lege."},
{"g":3,"b":2,"k":"h","q":"Hvad svarer man høfligt på 'Thank you!'?","o":["Goodbye!","You're welcome!","I'm sorry!","Me too!"],"a":"You're welcome!","r":"'You're welcome' betyder 'selv tak' eller 'det var så lidt'."},
{"g":3,"b":2,"k":"h","q":"Hvad betyder 'Help!'?","o":["Hjælp!","Hej!","Stop!","Hurra!"],"a":"Hjælp!","r":"'Help' betyder hjælp. 'Can you help me?' = kan du hjælpe mig?"},
{"g":3,"b":2,"k":"g","q":"Hvilket ord mangler? 'You ___ my friend.'","o":["am","is","be","are"],"a":"are","r":"Med 'you' (du) bruger man 'are': You are my friend = du er min ven."},
{"g":3,"b":2,"k":"g","q":"Hvilket ord mangler? 'She ___ a cat.'","o":["have","is","has","are"],"a":"has","r":"Med 'he', 'she' og 'it' bruger man 'has': She has a cat = hun har en kat."},
{"g":3,"b":2,"k":"g","q":"Hvilket ord mangler? 'We ___ happy.'","o":["is","are","am","has"],"a":"are","r":"Med 'we' (vi) bruger man 'are': We are happy = vi er glade."},
{"g":3,"b":2,"k":"g","q":"Hvad er flertal af 'book' (flere bøger)?","o":["books","bookes","book","bookies"],"a":"books","r":"Man sætter -s på: one book, two books."},
{"g":3,"b":2,"k":"g","q":"Hvad er flertal af 'box' (flere kasser)?","o":["boxs","box","boxies","boxes"],"a":"boxes","r":"Efter x tilføjer man -es: one box, two boxes."},
{"g":3,"b":2,"k":"g","q":"Hvad betyder 'he'?","o":["hun","det","han","vi"],"a":"han","r":"'He' betyder han. Hun hedder 'she'."},
{"g":3,"b":2,"k":"g","q":"Hvad betyder 'they'?","o":["vi","de","du","den"],"a":"de","r":"'They' betyder de. 'They are my friends' = de er mine venner."},
{"g":3,"b":2,"k":"g","q":"Hvilket ord mangler? 'I ___ swim.' (jeg kan svømme)","o":["can","am","has","is"],"a":"can","r":"'Can' betyder kan: I can swim = jeg kan svømme."},
{"g":3,"b":2,"k":"g","q":"Hvilket ord betyder 'min'?","o":["me","I","you","my"],"a":"my","r":"'My' betyder min eller mit: my dog = min hund."},
{"g":3,"b":2,"k":"g","q":"Hvilket ord mangler? 'This is ___ dog.' (hans hund)","o":["her","he","his","him"],"a":"his","r":"'His' betyder hans: his dog = hans hund. 'Her' betyder hendes."},
{"g":3,"b":2,"k":"g","q":"Hvilket ord mangler? 'He ___ ten years old.'","o":["are","is","am","have"],"a":"is","r":"Med 'he' bruger man 'is'. På engelsk ER man sin alder: He is ten."},
{"g":3,"b":2,"k":"l","q":"Læs: 'Sam has a blue bike and a red ball.' Hvilken farve har cyklen?","o":["blå","rød","grøn","gul"],"a":"blå","r":"'A blue bike' = en blå cykel. Bolden er rød."},
{"g":3,"b":2,"k":"l","q":"Læs: 'Lily is sad. She lost her doll.' Hvorfor er Lily ked af det?","o":["Hun er syg","Hun er sulten","Hun har fået en dukke","Hun har mistet sin dukke"],"a":"Hun har mistet sin dukke","r":"'Lost' betyder mistede. Lily mistede sin dukke (doll)."},
{"g":3,"b":2,"k":"l","q":"Læs: 'I have three sisters and one brother.' Hvor mange søskende har personen?","o":["tre","en","fire","to"],"a":"fire","r":"Tre søstre + en bror = fire søskende."},
{"g":3,"b":2,"k":"l","q":"Læs: 'My cat sleeps on my bed.' Hvor sover katten?","o":["i haven","på sengen","på stolen","i køkkenet"],"a":"på sengen","r":"'On my bed' betyder på min seng."},
{"g":3,"b":2,"k":"l","q":"Læs: 'Today is Monday. Tomorrow is ___.' Hvilken dag mangler?","o":["Tuesday","Sunday","Friday","Wednesday"],"a":"Tuesday","r":"Efter mandag (Monday) kommer tirsdag (Tuesday)."},
{"g":3,"b":2,"k":"l","q":"Læs: 'Max likes milk, but he doesn't like juice.' Hvad kan Max IKKE lide?","o":["mælk","is","vand","juice"],"a":"juice","r":"'Doesn't like' betyder 'kan ikke lide'. Max kan ikke lide juice."},
{"g":3,"b":2,"k":"l","q":"Læs: 'It is cold. Put on your hat!' Hvorfor skal man tage hue på?","o":["Det regner","Det er varmt","Det er koldt","Det er mørkt"],"a":"Det er koldt","r":"'Cold' betyder koldt. Derfor skal man have hue (hat) på."},
{"g":3,"b":2,"k":"l","q":"Læs: 'The dog is under the table.' Hvor er hunden?","o":["på bordet","under bordet","ved døren","i sengen"],"a":"under bordet","r":"'Under' betyder under, og 'table' er bord."},
{"g":3,"b":2,"k":"l","q":"Læs: 'Emma can run, but she can't swim.' Hvad kan Emma IKKE?","o":["svømme","løbe","læse","synge"],"a":"svømme","r":"'Can't' betyder 'kan ikke'. Emma kan ikke svømme (swim)."},
{"g":3,"b":2,"k":"l","q":"Læs: 'I am hungry. Can I have a sandwich?' Hvad vil personen have?","o":["et glas vand","en bog","en bold","en sandwich"],"a":"en sandwich","r":"'Hungry' er sulten, og personen beder om en sandwich."}
]$$::jsonb) AS e
JOIN (VALUES
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('h', 'hverdagsudtryk', 'comprehension', 'conceptual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
